		{
			id = "prot_tank",
			role = "TANK",
			name = { en = "Protection Tank (Standard, 4/15/32)", ru = "Защита, танк (стандартный, 4/15/32)" },
			summary = { en = "Wowhead's standard Protection build. It takes all the core shield talents: Shield Specialization, Defiance, Master of Defense, Last Stand, Improved Shield Wall, Bastion and Shield Slam. Vanguard lets you Charge in Defensive Stance. After that it adds Cruelty, Unbridled Wrath and Enrage in Fury for threat and Rage. It works for dungeons and raids. Protection is also a strong leveling spec in Forever.", ru = "Стандартный билд «Защита» с Wowhead. Он берёт все ключевые таланты для щита: «Специализация на щитах», «Неукротимость», «Мастер обороны», «Ни шагу назад», «Улучшенная глухая оборона», «Бастион» и «Сокрушение щитом». «Авангард» позволяет делать «Рывок» в «Оборонительной стойке». После этого билд берёт «Безжалостность», «Необузданный гнев» и «Исступление» в «Неистовстве» ради угрозы и ярости. Подходит для подземелий и рейдов. «Защита» в Forever также сильна для прокачки." },
			order = {
